//! Owner-facts regression suite (025/028): each case drives
//! `check_deploy_modules` with host-frontend facts generated by
//! `scanModuleFacts` and asserts byte-identical owner verdicts.
use can_preparation::input::decode_tree;
use can_preparation::modules::{check_deploy_modules, decode_module_facts, validate_module_facts};

fn units(text: &str) -> Vec<u16> {
    text.encode_utf16().collect::<Vec<_>>()
}

fn run_case(modules: &[(&str, &str, &str)], binaries: &[&str], expected: Result<usize, String>) {
    let owned: Vec<(Vec<u16>, Vec<u16>, can_preparation::modules::ModuleFacts)> = modules
        .iter()
        .map(|(key, js, wire)| {
            let node = decode_tree(wire.as_bytes()).expect("facts wire decodes");
            let facts = decode_module_facts(&node).expect("facts shape decodes");
            let js_units = units(js);
            validate_module_facts(&units(key), &js_units, &facts).expect("facts validate");
            (units(key), js_units, facts)
        })
        .collect();
    let binary_units: Vec<Vec<u16>> = binaries.iter().map(|b| units(b)).collect();
    let got = check_deploy_modules(&owned, &binary_units).map_err(|e| e.message);
    assert_eq!(got, expected, "facts policy");
}

