#[test]
fn facts_frontend_error_forwards_verbatim() {
    let wire = r#"{"t":"obj","entries":[[[105,109,112,111,114,116,115],{"t":"arr","items":[]}],[[108,101,120,101,114,69,114,114,111,114],{"t":"null"}],[[102,114,111,110,116,101,110,100,69,114,114,111,114],{"t":"text","units":[111,119,110,101,114,32,98,111,111,109]}],[[115,121,110,116,97,120,69,114,114,111,114],{"t":"null"}],[[102,105,108,101,85,114,108],{"t":"arr","items":[]}],[[117,110,114,101,115,111,108,118,101,100],{"t":"arr","items":[]}]]}"#;
    let node = decode_tree(wire.as_bytes()).expect("wire decodes");
    let facts = decode_module_facts(&node).expect("shape decodes");
    validate_module_facts(&units("a.js"), &units("import x;"), &facts).expect("validates");
    let owned = vec![(units("a.js"), units("import x;"), facts)];
    let got = check_deploy_modules(&owned, &[]).map_err(|e| e.message);
    assert_eq!(got, Err("owner boom".to_string()), "verbatim");
}

#[test]
fn facts_malformed_shape_refuses_decode() {
    let wire = r#"{"t":"obj","entries":[]}"#;
    let node = decode_tree(wire.as_bytes()).expect("wire decodes");
    assert!(decode_module_facts(&node).is_err(), "missing members refuse");
}

#[test]
fn facts_braced_escape_ident() {
    // Owner: decoded `exports` at original span [0, 12).
    let js = "exp\\u{6f}rts.x = 1;";
    let wire = "{\"t\":\"obj\",\"entries\":[[[105,109,112,111,114,116,115],{\"t\":\"arr\",\"items\":[]}],[[108,101,120,101,114,69,114,114,111,114],{\"t\":\"null\"}],[[102,114,111,110,116,101,110,100,69,114,114,111,114],{\"t\":\"null\"}],[[115,121,110,116,97,120,69,114,114,111,114],{\"t\":\"null\"}],[[102,105,108,101,85,114,108],{\"t\":\"arr\",\"items\":[]}],[[117,110,114,101,115,111,108,118,101,100],{\"t\":\"arr\",\"items\":[{\"t\":\"obj\",\"entries\":[[[103,114,111,117,112],{\"t\":\"num\",\"bits\":\"4000000000000000\",\"spelling\":\"2\"}],[[115,116,97,114,116],{\"t\":\"num\",\"bits\":\"0000000000000000\",\"spelling\":\"0\"}],[[101,110,100],{\"t\":\"num\",\"bits\":\"4028000000000000\",\"spelling\":\"12\"}],[[110,97,109,101],{\"t\":\"text\",\"units\":[101,120,112,111,114,116,115]}]]}]}]]}";
    let node = decode_tree(wire.as_bytes()).expect("wire decodes");
    let facts = decode_module_facts(&node).expect("shape decodes");
    let js_units = units(js);
    validate_module_facts(&units("a.js"), &js_units, &facts).expect("validates");
    let owned = vec![(units("a.js"), js_units, facts)];
    let got = check_deploy_modules(&owned, &[]).map_err(|e| e.message);
    assert_eq!(
        got,
        Err("deploy bundle: module \"a.js\" is not workerd-loadable: CommonJS free exports at offset 0".to_string()),
        "braced escape",
    );
}
